use super::columns::{HFROUNDS, NUM_INTERNAL_ROUNDS, WIDTH};
use p3_field::Field;

#[derive(Debug)]
pub struct RoundConstants<F: Field> {
    pub(crate) beginning_full_round_constants: [[F; WIDTH]; HFROUNDS],
    pub(crate) partial_round_constants: [F; NUM_INTERNAL_ROUNDS],
    pub(crate) ending_full_round_constants: [[F; WIDTH]; HFROUNDS],
}

impl<F: Field> Default for RoundConstants<F> {
    fn default() -> Self {
        let beginning_full_round_constants =
            RC24_EXTERNAL_INITIAL.map(|row| row.map(|val| F::from_canonical_u32(val)));
        let partial_round_constants = RC24_INTERNAL.map(|val| F::from_canonical_u32(val));
        let ending_full_round_constants =
            RC24_EXTERNAL_FINAL.map(|row| row.map(|val| F::from_canonical_u32(val)));
        Self {
            beginning_full_round_constants,
            partial_round_constants,
            ending_full_round_constants,
        }
    }
}

